The user wants a compact weather dashboard in a single HTML file with:
- Dark theme
- City search field
- Sample weather data
- Responsive design
- Inline CSS and JavaScript
- No external dependencies

Let me build a clean, functional weather dashboard with:
- A search bar to "search" cities (using sample data)
- Display current weather, forecast, and details
- Dark theme styling
- Responsive layout

I'll create sample data for several cities and make the search filter through them.
</think>

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Weather Dashboard</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    background: #0f1117;
    color: #e0e0e0;
    min-height: 100vh;
    padding: 20px;
  }
  .container { max-width: 800px; margin: 0 auto; }
  h1 {
    text-align: center;
    font-size: 1.5rem;
    font-weight: 600;
    margin-bottom: 20px;
    color: #fff;
    letter-spacing: -0.5px;
  }
  .search-wrap {
    position: relative;
    margin-bottom: 24px;
  }
  .search-wrap input {
    width: 100%;
    padding: 12px 16px 12px 42px;
    border: 1px solid #2a2d37;
    border-radius: 12px;
    background: #1a1d27;
    color: #fff;
    font-size: 0.95rem;
    outline: none;
    transition: border-color 0.2s;
  }
  .search-wrap input:focus { border-color: #4a90d9; }
  .search-wrap input::placeholder { color: #555; }
  .search-icon {
    position: absolute;
    left: 14px;
    top: 50%;
    transform: translateY(-50%);
    color: #555;
    font-size: 1.1rem;
    pointer-events: none;
  }
  .card {
    background: #1a1d27;
    border: 1px solid #2a2d37;
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 16px;
  }
  .current-weather {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 16px;
  }
  .current-left h2 { font-size: 1.1rem; color: #888; font-weight: 400; }
  .current-left .temp {
    font-size: 3.5rem;
    font-weight: 700;
    color: #fff;
    line-height: 1.1;
  }
  .current-left .desc {
    font-size: 1rem;
    color: #4a90d9;
    margin-top: 4px;
    text-transform: capitalize;
  }
  .current-left .details {
    font-size: 0.85rem;
    color: #666;
    margin-top: 8px;
  }
  .weather-icon { font-size: 4rem; }
  .grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 12px;
  }
  .grid-item {
    background: #12141c;
    border-radius: 12px;
    padding: 14px;
    text-align: center;
  }
  .grid-item .label { font-size: 0.75rem; color: #555; text-transform: uppercase; letter-spacing: 0.5px; }
  .grid-item .value { font-size: 1.3rem; font-weight: 600; color: #fff; margin-top: 4px; }
  .grid-item .unit { font-size: 0.8rem; color: #666; }
  .forecast-title { font-size: 0.95rem; color: #888; margin-bottom: 12px; font-weight: 500; }
  .forecast-row {
    display: flex;
    gap: 10px;
    overflow-x: auto;
    padding-bottom: 4px;
  }
  .forecast-row::-webkit-scrollbar { height: 4px; }
  .forecast-row::-webkit-scrollbar-thumb { background: #2a2d37; border-radius: 4px; }
  .forecast-day {
    flex: 0 0 80px;
    background: #12141c;
    border-radius: 12px;
    padding: 14px 10px;
    text-align: center;
  }
  .forecast-day .day { font-size: 0.8rem; color: #666; }
  .forecast-day .icon { font-size: 1.6rem; margin: 6px 0; }
  .forecast-day .high { font-size: 1rem; font-weight: 600; color: #fff; }
  .forecast-day .low { font-size: 0.85rem; color: #555; }
  .no-results {
    text-align: center;
    padding: 40px 20px;
    color: #555;
  }
  .no-results .emoji { font-size: 2.5rem; margin-bottom: 12px; }
  @media (max-width: 500px) {
    .current-weather { flex-direction: column; text-align: center; }
    .current-left .temp { font-size: 2.8rem; }
    .weather-icon { font-size: 3rem; }
  }
</style>
</head>
<body>
<div class="container">
  <h1>⛅ Weather Dashboard</h1>
  <div class="search-wrap">
    <span class="search-icon">🔍</span>
    <input type="text" id="search" placeholder="Search city..." autocomplete="off">
  </div>
  <div id="output"></div>
</div>

<script>
const weatherData = [
  { city: "London", country: "UK", temp: 12, desc: "Partly Cloudy", icon: "⛅", humidity: 72, wind: 18, pressure: 1013, uv: 3, feelsLike: 10, forecast: [
    { day: "Mon", icon: "🌧️", high: 13, low: 8 }, { day: "Tue", icon: "☁️", high: 11, low: 7 },
    { day: "Wed", icon: "⛅", high: 14, low: 9 }, { day: "Thu", icon: "🌤️", high: 16, low: 10 },
    { day: "Fri", icon: "🌧️", high: 12, low: 7 }
  ]},
  { city: "Tokyo", country: "Japan", temp: 24, desc: "Clear Sky", icon: "☀️", humidity: 45, wind: 12, pressure: 1018, uv: 7, feelsLike: 26, forecast: [
    { day: "Mon", icon: "☀️", high: 26, low: 19 }, { day: "Tue", icon: "🌤️", high: 25, low: 18 },
    { day: "Wed", icon: "⛅", high: 23, low: 17 }, { day: "Thu", icon: "🌧️", high: 21, low: 16 },
    { day: "Fri", icon: "☀️", high: 25, low: 18 }
  ]},
  { city: "New York", country: "USA", temp: 18, desc: "Overcast", icon: "☁️", humidity: 60, wind: 22, pressure: 1010, uv: 4, feelsLike: 16, forecast: [
    { day: "Mon", icon: "☁️", high: 19, low: 12 }, { day: "Tue", icon: "🌧️", high: 15, low: 10 },
    { day: "Wed", icon: "⛅", high: 17, low: 11 }, { day: "Thu", icon: "☀️", high: 20, low: 13 },
    { day: "Fri", icon: "☀️", high: 22, low: 14 }
  ]},
  { city: "Sydney", country: "Australia", temp: 28, desc: "Sunny", icon: "🌞", humidity: 55, wind: 15, pressure: 1015, uv: 9, feelsLike: 30, forecast: [
    { day: "Mon", icon: "🌞", high: 29, low: 21 }, { day: "Tue", icon: "🌤️", high: 27, low: 20 },
    { day: "Wed", icon: "⛅", high: 25, low: 19 }, { day: "Thu", icon: "🌧️", high: 22, low: 17 },
    { day: "Fri", icon: "🌞", high: 28, low: 20 }
  ]},
  { city: "Paris", country: "France", temp: 15, desc: "Light Rain", icon: "🌧️", humidity: 78, wind: 14, pressure: 1008, uv: 2, feelsLike: 13, forecast: [
    { day: "Mon", icon: "🌧️", high: 14, low: 9 }, { day: "Tue", icon: "☁️", high: 16, low: 10 },
    { day: "Wed", icon: "⛅", high: 18, low: 11 }, { day: "Thu", icon: "☀️", high: 20, low: 12 },
    { day: "Fri", icon: "🌤️", high: 19, low: 11 }
  ]},
  { city: "Dubai", country: "UAE", temp: 38, desc: "Hot & Sunny", icon: "🔥", humidity: 30, wind: 20, pressure: 1005, uv: 11, feelsLike: 42, forecast: [
    { day: "Mon", icon: "🔥", high: 40, low: 30 }, { day: "Tue", icon: "☀️", high: 39, low: 29 },
    { day: "Wed", icon: "🌤️", high: 37, low: 28 }, { day: "Thu", icon: "🔥", high: 41, low: 31 },
    { day: "Fri", icon: "☀️", high: 38, low: 29 }
  ]},
  { city: "Moscow", country: "Russia", temp: -5, desc: "Snow", icon: "❄️", humidity: 85, wind: 25, pressure: 1020, uv: 1, feelsLike: -12, forecast: [
    { day: "Mon", icon: "❄️", high: -4, low: -10 }, { day: "Tue", icon: "🌨️", high: -6, low: -12 },
    { day: "Wed", icon: "❄️", high: -3, low: -9 }, { day: "Thu", icon: "☁️", high: -2, low: -8 },
    { day: "Fri", icon: "🌨️", high: -5, low: -11 }
  ]},
  { city: "Mumbai", country: "India", temp: 32, desc: "Humid", icon: "🌴", humidity: 80, wind: 10, pressure: 1007, uv: 8, feelsLike: 38, forecast: [
    { day: "Mon", icon: "🌤️", high: 33, low: 27 }, { day: "Tue", icon: "⛈️", high: 30, low: 26 },
    { day: "Wed", icon: "🌧️", high: 29, low: 25 }, { day: "Thu", icon: "⛅", high: 31, low: 26 },
    { day: "Fri", icon: "🌤️", high: 33, low: 27 }
  ]}
];

const output = document.getElementById('output');
const searchInput = document.getElementById('search');

function renderWeather(data) {
  if (!data) {
    output.innerHTML = `<div class="no-results"><div class="emoji">🌍</div><p>Search for a city to see weather details</p></div>`;
    return;
  }
  const { city, country, temp, desc, icon, humidity, wind, pressure, uv, feelsLike, forecast } = data;
  output.innerHTML = `
    <div class="card">
      <div class="current-weather">
        <div class="current-left">
          <h2>${city}, ${country}</h2>
          <div class="temp">${temp}°C</div>
          <div class="desc">${desc}</div>
          <div class="details">Feels like ${feelsLike}°C · ${new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}</div>
        </div>
        <div class="weather-icon">${icon}</div>
      </div>
    </div>
    <div class="card">
      <div class="grid">
        <div class="grid-item"><div class="label">Humidity</div><div class="value">${humidity}<span class="unit">%</span></div></div>
        <div class="grid-item"><div class="label">Wind</div><div class="value">${wind}<span class="unit"> km/h</span></div></div>
        <div class="grid-item"><div class="label">Pressure</div><div class="value">${pressure}<span class="unit"> hPa</span></div></div>
        <div class="grid-item"><div class="label">UV Index</div><div class="value">${uv}<span class="unit"> ${uv <= 2 ? 'Low' : uv <= 5 ? 'Moderate' : uv <= 7 ? 'High' : 'Extreme'}</span></div></div>
      </div>
    </div>
    <div class="card">
      <div class="forecast-title">5-Day Forecast</div>
      <div class="forecast-row">
        ${forecast.map(d => `
          <div class="forecast-day">
            <div class="day">${d.day}</div>
            <div class="icon">${d.icon}</div>
            <div class="high">${d.high}°</div>
            <div class="low">${d.low}°</div>
          </div>
        `).join('')}
      </div>
    </div>
  `;
}

searchInput.addEventListener('input', (e) => {
  const q = e.target.value.trim().toLowerCase();
  if (!q) { renderWeather(null); return; }
  const found = weatherData.find(d => d.city.toLowerCase().includes(q) || d.country.toLowerCase().includes(q));
  renderWeather(found || null);
});

renderWeather(null);
</script>
</body>
</html>
```
